import re
import xml.etree.ElementTree as ET

def grant_monitoring(xml,unit_paths):
    destination='org.freedesktop.systemd1';root_path='/org/freedesktop/systemd1'
    if not isinstance(unit_paths,list) or not 1<=len(unit_paths)<=8 or len(set(unit_paths))!=len(unit_paths):
        raise ValueError('explicit bounded unit paths required')
    if any(not isinstance(path,str) or re.fullmatch(root_path+r'/unit/[A-Za-z_][A-Za-z0-9_]*',path) is None for path in unit_paths):
        raise ValueError('unit object path outside approved scope')
    try:root=ET.fromstring(xml)
    except ET.ParseError as error:raise ValueError('invalid private-bus XML') from error
    policies=root.findall('policy')
    if root.tag!='busconfig' or len(policies)!=1 or policies[0].attrib!={'context':'default'}:
        raise ValueError('expected the declared private-bus policy')
    policy=policies[0]
    if not any(element.tag=='deny' and element.attrib=={'send_destination':destination} for element in policy):
        raise ValueError('existing destination deny must remain')
    rules=[{'send_destination':destination,'send_interface':destination+'.Manager','send_member':'ListUnits','send_path':root_path}]
    rules += [{'send_destination':destination,'send_interface':'org.freedesktop.DBus.Properties','send_member':'Get','send_path':path} for path in [root_path,*sorted(unit_paths)]]
    for rule in rules:
        if not any(element.tag=='allow' and element.attrib==rule for element in policy):
            ET.SubElement(policy,'allow',rule)
    return ET.tostring(root,encoding='unicode')
