from dbus_next.aio import MessageBus
DEST='org.freedesktop.systemd1';ROOT_PATH='/org/freedesktop/systemd1'
DENIED='org.freedesktop.DBus.Error.AccessDenied'

def unit_path(name):
 return ROOT_PATH+'/unit/'+''.join(c if c.isascii() and c.isalnum() else '_'+format(ord(c),'02x') for c in name)

async def provider(address,catalog):
 bus=await MessageBus(bus_address=address).connect()
 unrelated=await MessageBus(bus_address=address).connect()
 await bus.request_name(DEST);await unrelated.request_name('org.opsforge.Unrelated')
 def handler(message):
  if message.message_type!=MessageType.METHOD_CALL:return
  if message.interface=='org.opsforge.Unrelated' and message.member=='Ping':
   return Message.new_method_return(message,signature='s',body=['old-permission'])
  if message.interface==DEST+'.Manager' and message.member=='ListUnits':
   rows=[[name,'controlled fixture','loaded',state,'running' if state=='active' else 'failed','',unit_path(name),0,'','/'] for name,state in catalog.items()]
   return Message.new_method_return(message,signature='a(ssssssouso)',body=[rows])
  if message.interface=='org.freedesktop.DBus.Properties' and message.member=='Get':
   interface,prop=message.body
   values={(ROOT_PATH,DEST+'.Manager','Version'):'252.0',
           (ROOT_PATH,DEST+'.Manager','SystemState'):'running'}
   values.update({(unit_path(name),DEST+'.Service','Type'):'simple' for name in catalog})
   value=values.get((message.path,interface,prop))
   if value is not None:return Message.new_method_return(message,signature='v',body=[Variant('s',value)])
  if message.interface==DEST+'.Manager' and message.member in ('StartUnit','RestartUnit'):
   return Message.new_method_return(message,signature='o',body=[ROOT_PATH+'/job/1'])
  return Message.new_error(message,'org.freedesktop.DBus.Error.UnknownMethod','controlled endpoint has no such method')
