  self.spawn('daemon',['dbus-daemon','--nofork','--nopidfile','--config-file='+str(self.config)])
  deadline=time.monotonic()+4
  while not (self.root/'bus.sock').exists():
   assert self.processes[0].poll() is None and time.monotonic()<deadline,self.logtext();time.sleep(.02)
